'use client';
import { useMemo,useState,useRef,useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { motion,useReducedMotion } from 'motion/react';
import { LayoutDashboard,Package,ShoppingBag,ArrowUpRight,ArrowDownLeft,Wallet,Search,Plus,X,Check,ArrowRight,LogOut,Menu,Download,Grid2X2,List,AlertCircle,CheckCircle2,Banknote,Building2,CreditCard,History,ChevronRight,Layers,Users,Truck,ClipboardList,BarChart3,Brain,Lightbulb,Settings,Bell,FileSpreadsheet,Calculator,Boxes,Factory } from 'lucide-react';
import { AreaChart,Area,XAxis,YAxis,Tooltip,ResponsiveContainer,CartesianGrid } from 'recharts';
import { saveOperation,logout } from '@/app/actions';
import SuiteForm from './suite-forms';
import SuitePage,{suitePages,type SuitePageName} from './suite-page';
import ImportInventory from './import-inventory';
import FileUpload from './file-upload';
import { currency,dateLabel,type Snapshot,type Document,type Product } from '@/lib/types';

type Page='Dashboard'|'Inventario'|'Compras'|'Ventas'|'Confirmación de pagos'|'Finanzas'|'Movimientos'|SuitePageName;
type FormKind='product'|'purchase'|'sale'|'capital'|'expense'|'withdrawal'|'transfer'|'payment'|'purchase_payment'|'edit_product'|'reverse_sale';
const titles:Record<FormKind,string>={product:'Un nuevo diseño',purchase:'Registrar compra',sale:'Registrar venta',capital:'Aportación de capital',expense:'Registrar gasto',withdrawal:'Retiro personal',transfer:'Transferir entre cuentas',payment:'Reportar un abono',purchase_payment:'Pagar a un proveedor',edit_product:'Editar diseño',reverse_sale:'Devolución o anulación total'};
const icons:Record<string,typeof Layers>={Dashboard:LayoutDashboard,Inventario:Package,Compras:ArrowDownLeft,Ventas:ShoppingBag,Finanzas:Wallet,Movimientos:History,'Clientes':Users,'Proveedores':Factory,'Presentaciones':Boxes,'Pedidos':ClipboardList,'Entregas pendientes':Truck,'Cobros pendientes':CreditCard,'Bancos y cuentas':Building2,'Estadísticas':BarChart3,'Inteligencia comercial':Brain,'Oportunidades de venta':Lightbulb,'Simulador de precios':Calculator,'Gastos':Wallet,'Reportes':FileSpreadsheet,'Notificaciones':Bell,'Configuración':Settings,'Confirmación de pagos':CreditCard};
const kindLabel:Record<string,string>={capital:'Aportación',expense:'Gasto',withdrawal:'Retiro',transfer:'Transferencia propia',purchase:'Pago de compra',collection:'Cobro',refund:'Reverso de cobro',adjustment:'Ajuste de patrimonio'};
const paymentLabel:Record<string,string>={pending:'Por confirmar',confirmed:'Confirmado',rejected:'Rechazado',reversed:'Reversado'};
const dateKey=(date:string)=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santo_Domingo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(date));
function exportCsv(filename:string,rows:unknown[][]){
 const csv='\uFEFF'+rows.map(row=>row.map(value=>{let text=String(value??'');if(/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';}).join(',')).join('\r\n');
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));
 const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);
}
function Empty({text,action}:{text:string;action?:React.ReactNode}){return <div className="empty"><Layers size={32}/><h3>Tu próxima historia empieza aquí.</h3><p>{text}</p>{action}</div>;}
function Metric({label,value,detail,accent=false,onClick}:{label:string;value:string;detail:string;accent?:boolean;onClick?:()=>void}){return <button className={`metric ${accent?'accent':''}`} onClick={onClick}><span>{label}</span><strong>{value}</strong><small>{detail}</small><ArrowUpRight size={18}/></button>;}

export default function Workspace({data,local,demo=false}:{data:Snapshot;local:boolean;demo?:boolean}) {
 const [page,setPage]=useState<Page>('Dashboard');
 const [importing,setImporting]=useState(false);
 const [suiteReturn,setSuiteReturn]=useState<string|null>(null);
 const [suiteTransfer,setSuiteTransfer]=useState(false);
 const isSuite=suitePages.includes(page as SuitePageName);
 const [mobile,setMobile]=useState(false);
 const [form,setForm]=useState<FormKind|null>(null);
 const [detail,setDetail]=useState<Document|null>(null);
 const [photoGallery,setPhotoGallery]=useState<Product|null>(null);
 const [editing,setEditing]=useState<Product|null>(null);
 const [initialDocument,setInitialDocument]=useState('');
 const [toast,setToast]=useState('');
 const [busy,setBusy]=useState(false);
 const [search,setSearch]=useState('');
 const [category,setCategory]=useState('');
 const [sort,setSort]=useState('name');
 const [gallery,setGallery]=useState(false);
 const [from,setFrom]=useState(''); const [to,setTo]=useState('');
 const [chartPairs,setChartPairs]=useState(false);
 const router=useRouter(); const reduced=useReducedMotion();
 const activitySales=data.documents.filter(d=>d.kind==='sale'&&d.status==='active'&&(!from||dateKey(d.created_at)>=from)&&(!to||dateKey(d.created_at)<=to));
 const activityExpenses=-data.movements.filter(m=>m.kind==='expense'&&(!from||dateKey(m.created_at)>=from)&&(!to||dateKey(m.created_at)<=to)).reduce((n,m)=>n+Number(m.amount),0);
 const revenue=activitySales.reduce((n,d)=>n+Math.round(Number(d.total)*100),0)/100,cogs=activitySales.reduce((n,d)=>n+Math.round(Number(d.cogs)*100),0)/100;
 const metrics:Record<string,number>={...data.metrics};if(page==='Dashboard')Object.assign(metrics,{revenue,cogs,gross_profit:revenue-cogs,expenses:activityExpenses,net_profit:revenue-cogs-activityExpenses});
 const pending=data.payments.filter(p=>p.status==='pending');
 const low=data.products.filter(p=>p.active&&p.available<=p.minimum);
 const goto=(next:Page)=>{setPage(next);setMobile(false);setSearch('');setFrom('');setTo('');window.scrollTo({top:0,behavior:'auto'});};
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),6000);return()=>clearTimeout(t);},[toast]);
 const run=async(kind:string,payload:unknown)=>{
  if(busy)return;setBusy(true);
  try{const r=await saveOperation(kind,payload,crypto.randomUUID());if(!r.ok)setToast(r.error??'No se pudo completar');else{setToast('Movimiento registrado y verificado.');router.refresh();}}catch{setToast('Se perdió la conexión. Revisa el movimiento antes de reintentar.');}finally{setBusy(false);}
 };
 const filteredProducts=useMemo(()=>data.products.filter(p=>(`${p.name} ${p.sku} ${p.color}`.toLowerCase().includes(search.toLowerCase()))&&(!category||p.category===category)).sort((a,b)=>sort==='sales'?data.lines.filter(l=>l.product_id===b.id&&data.documents.some(d=>d.id===l.document_id&&d.kind==='sale'&&d.status==='active')).reduce((n,l)=>n+l.quantity,0)-data.lines.filter(l=>l.product_id===a.id&&data.documents.some(d=>d.id===l.document_id&&d.kind==='sale'&&d.status==='active')).reduce((n,l)=>n+l.quantity,0):sort==='stock'?a.available-b.available:sort==='price'?Number(a.price)-Number(b.price):a.name.localeCompare(b.name)),[data.products,data.lines,data.documents,search,category,sort]);
 const filteredDocs=data.documents.filter(d=>d.kind===(page==='Compras'?'purchase':'sale')&&`${d.contact} ${d.reference} ${d.id}`.toLowerCase().includes(search.toLowerCase())&&(!from||dateKey(d.created_at)>=from)&&(!to||dateKey(d.created_at)<=to));
 const monthSeries=useMemo(()=>{
  const months=new Map<string,{name:string;revenue:number;pairs:number}>();
  const now=new Date();
  const monthParts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santo_Domingo',year:'numeric',month:'2-digit'}).formatToParts(now);
  const year=Number(monthParts.find(p=>p.type==='year')!.value), month=Number(monthParts.find(p=>p.type==='month')!.value)-1;
  const end=to?new Date(`${to.slice(0,7)}-15T00:00:00Z`):new Date(Date.UTC(year,month,15));const start=from?new Date(`${from.slice(0,7)}-15T00:00:00Z`):new Date(Date.UTC(end.getUTCFullYear(),end.getUTCMonth()-5,15));const count=(end.getUTCFullYear()-start.getUTCFullYear())*12+end.getUTCMonth()-start.getUTCMonth();
  for(let i=0;i<=count;i++){const date=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+i,15));const key=date.toISOString().slice(0,7);months.set(key,{name:new Intl.DateTimeFormat('es-DO',{month:'short',timeZone:'UTC'}).format(date),revenue:0,pairs:0});}
  for(const d of data.documents.filter(d=>d.kind==='sale'&&d.status==='active'&&(!from||dateKey(d.created_at)>=from)&&(!to||dateKey(d.created_at)<=to))){const entry=months.get(dateKey(d.created_at).slice(0,7));if(entry){entry.revenue+=Number(d.total);entry.pairs+=data.lines.filter(l=>l.document_id===d.id).reduce((a,l)=>a+Number(l.quantity),0);}}
  return Array.from(months.values());
 },[data.documents,data.lines,from,to]);
 const bestsellers=useMemo(()=>data.products.map(p=>({...p,sold:data.lines.filter(l=>l.product_id===p.id&&data.documents.some(d=>d.id===l.document_id&&d.kind==='sale'&&d.status==='active')).reduce((n,l)=>n+l.quantity,0)})).filter(p=>p.sold>0).sort((a,b)=>b.sold-a.sold).slice(0,4),[data]);
 const paidFor=(id:string)=>data.payments.filter(p=>p.document_id===id&&p.status==='confirmed').reduce((a,p)=>a+Math.round(Number(p.amount)*100),0)/100;
 const navigation=(['Dashboard','Inventario','Presentaciones','Clientes','Proveedores','Compras','Ventas','Pedidos','Entregas pendientes','Cobros pendientes','Confirmación de pagos','Bancos y cuentas','Finanzas','Gastos','Movimientos','Estadísticas','Inteligencia comercial','Oportunidades de venta','Simulador de precios','Reportes','Notificaciones','Configuración'] as Page[]).map((item,index)=>{const Icon=icons[item]??Layers;return <div key={item}>{['Dashboard','Inventario','Cobros pendientes','Estadísticas','Reportes'].includes(item)&&<span className="nav-group">{item==='Dashboard'?'TU NEGOCIO':item==='Inventario'?'OPERACIÓN':item==='Cobros pendientes'?'COBROS Y FINANZAS':item==='Estadísticas'?'INTELIGENCIA':'HERRAMIENTAS'}</span>}<button className={page===item?'nav-item selected':'nav-item'} onClick={()=>goto(item)}><Icon size={19}/>{item}{item==='Confirmación de pagos'&&pending.length>0&&<span className="nav-count">{pending.length}</span>}</button></div>;});
 return <div className="app-shell">
  {mobile&&<button className="sidebar-backdrop" aria-label="Cerrar navegación" onClick={()=>setMobile(false)}/>}
  <aside className={`sidebar ${mobile?'open':''}`}><div className="brand"><img src="/brand/optimized/logos/principal.svg" alt="SOCKIT" width="185" height="45"/><span>BUSINESS MANAGER</span></div><nav aria-label="Navegación principal">{navigation}</nav><div className="sidebar-note"><span className="mini-stitches"><Layers size={25}/></span><p>Un par para cada<br/><em>versión de tu negocio.</em></p></div><form action={logout}><button className="nav-item logout"><LogOut size={17}/>Cerrar sesión</button></form><div className="profile"><span>S</span><div><strong>{data.settings.name??'Mi negocio SOCKIT'}</strong><small>{demo?'Demostración privada':local?'Desarrollo local':'Cuenta privada'}</small></div><CheckCircle2 size={16}/></div></aside>
  <div className="main-shell"><header className="topbar"><button className="mobile-menu icon-button" aria-label="Abrir menú" onClick={()=>setMobile(true)}><Menu/></button><div className="breadcrumb">Mi negocio <ChevronRight size={14}/><strong>{page}</strong></div><div className="topbar-right"><span className="live-dot"/>Datos persistentes <button className="icon-button alerts" title="Ver cobros pendientes" aria-label={`Ver ${pending.length} cobros pendientes`} onClick={()=>goto('Confirmación de pagos')}><CreditCard size={19}/>{pending.length>0&&<i/>}</button><span className="avatar">S</span></div></header>
  <main className="content">
   {demo&&<div className="demo-banner" role="note" aria-label="Datos de demostración"><strong>DEMOSTRACIÓN</strong> Clientes, inventario, saldos y pagos ficticios. Tus pruebas se guardan en un entorno separado. No ingreses datos reales aquí.</div>}
   {local&&!demo&&<div className="local-banner"><span>DESARROLLO LOCAL</span> PostgreSQL persistente · Conecta Supabase antes de usar datos reales en producción.</div>}
   <motion.div key={page} initial={false} animate={{opacity:1,y:0}} transition={{duration:reduced?0:.2}}>
   {!isSuite&&<div className="page-heading"><div><span className="eyebrow">SOCKIT / {page==='Dashboard'?'EL PULSO DE TU NEGOCIO':page.toUpperCase()}</span><h1>{page==='Dashboard'?<>Tu negocio, <em>paso a paso.</em></>:page}</h1><p>{page==='Dashboard'?'Hoy toca vender más. Cada movimiento cuenta.':page==='Inventario'?'Cada diseño tiene su lugar. Cuida tu próxima gran venta.':page==='Finanzas'?'Tus números claros. Tus decisiones, con confianza.':'Todo al día. Así se hace.'}</p></div><button className="primary" onClick={()=>setForm(page==='Inventario'?'product':page==='Compras'?'purchase':page==='Finanzas'?'capital':'sale')}><Plus size={17}/>{page==='Inventario'?'Nuevo diseño':page==='Compras'?'Nueva compra':page==='Finanzas'?'Aportar capital':'Nueva venta'}</button></div>}
   {isSuite&&<SuitePage key={page} page={page as SuitePageName} data={data} onNavigate={next=>goto(next as Page)} onBaseForm={(kind,id)=>{setInitialDocument(id??'');if(kind==='sale_return'){setSuiteReturn(id??'');}else setForm(kind);}}/>}
   {page==='Dashboard'&&<><div className="toolbar dashboard-period"><label className="date-filter">Actividad desde<input aria-label="Actividad desde" type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label className="date-filter">Hasta<input aria-label="Actividad hasta" type="date" min={from} value={to} onChange={e=>setTo(e.target.value)}/></label><button className="text-button" onClick={()=>{setFrom('');setTo('');}}>Todo el historial</button><small>Filtra ventas y ganancias; saldos e inventario muestran el estado actual.</small></div>
    <div className="dashboard-top"><section className="hero-card"><span className="eyebrow">UNA MIRADA A LO QUE ESTÁS CREANDO</span><h2>Pequeños pares.<br/><em>Grandes pasos.</em></h2><p>Tu colección, tus ventas y tus finanzas.<br/>Todo conectado, todo bajo control.</p><button onClick={()=>goto('Inventario')}>Explorar mi colección <ArrowRight size={17}/></button><div className="hero-art" aria-hidden="true"><img src="/brand/icons/isotipo.png" alt=""/></div><span className="hero-caption">HECHO PARA CRECER CONTIGO</span></section><section className="balance-card"><span className="eyebrow">DINERO DISPONIBLE</span><strong>{currency(metrics.cash+metrics.bank)}</strong><p>Solo movimientos confirmados</p><div><span><Banknote size={17}/>Efectivo<strong>{currency(metrics.cash)}</strong></span><span><Building2 size={17}/>Banco<strong>{currency(metrics.bank)}</strong></span></div><button onClick={()=>goto('Finanzas')}>Ver mis finanzas <ArrowUpRight size={16}/></button></section></div>
    <div className="metric-grid"><Metric label="Ventas netas" value={currency(metrics.revenue)} detail={from||to?'Facturado en el período':'Total histórico facturado'} onClick={()=>goto('Ventas')}/><Metric label="Ganancia neta" value={currency(metrics.net_profit)} detail="Ventas − costo − gastos" accent onClick={()=>goto('Finanzas')}/><Metric label="Tu inventario" value={`${metrics.pairs} pares`} detail={`${data.products.filter(p=>p.active).length} diseños activos`} onClick={()=>goto('Inventario')}/><Metric label="Por cobrar" value={currency(metrics.receivables)} detail={`${pending.length} pagos por confirmar`} onClick={()=>goto('Confirmación de pagos')}/></div>
    <div className="dashboard-middle"><section className="panel chart-panel"><div className="panel-heading"><div><span className="eyebrow">ASÍ VA TU HISTORIA</span><h2>El ritmo de tus ventas</h2></div><div className="segmented"><button className={!chartPairs?'active':''} onClick={()=>setChartPairs(false)}>RD$</button><button className={chartPairs?'active':''} onClick={()=>setChartPairs(true)}>Pares</button></div></div><p className="muted chart-note">{from||to?'Período seleccionado':'Últimos seis meses'} · Ventas registradas</p><div className="chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={monthSeries} margin={{top:12,right:12,left:0,bottom:0}}><defs><linearGradient id="salesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#C4603F" stopOpacity={.28}/><stop offset="100%" stopColor="#C4603F" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#E6D8C3" strokeDasharray="3 5" vertical={false}/><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{fontSize:12,fill:'#70635d'}}/><YAxis tickLine={false} axisLine={false} width={52} tick={{fontSize:11,fill:'#70635d'}}/><Tooltip formatter={value=>chartPairs?`${value} pares`:currency(Number(value))} contentStyle={{background:'#F7EEE3',border:'1px solid #E6D8C3',borderRadius:12}}/><Area isAnimationActive={!reduced} type="monotone" dataKey={chartPairs?'pairs':'revenue'} name={chartPairs?'Pares':'Ventas'} stroke="#6E2A35" strokeWidth={2.5} fill="url(#salesFill)"/></AreaChart></ResponsiveContainer></div><table className="sr-only"><caption>Ventas mensuales</caption><thead><tr><th>Mes</th><th>Ventas</th><th>Pares</th></tr></thead><tbody>{monthSeries.map(m=><tr key={m.name}><td>{m.name}</td><td>{currency(m.revenue)}</td><td>{m.pairs}</td></tr>)}</tbody></table>{metrics.revenue===0&&<p className="chart-empty">Tu primera venta dará vida a este gráfico.</p>}</section><section className="panel attention-panel"><div className="panel-heading"><div><span className="eyebrow">QUE NO SE TE ESCAPE</span><h2>Un vistazo pendiente</h2></div><AlertCircle size={20}/></div><button className="attention-item" onClick={()=>goto('Inventario')}><span className="attention-icon"><Package size={20}/></span><div><strong>{low.length} diseños por reponer</strong><small>En su mínimo o agotados</small></div><ArrowUpRight size={17}/></button><button className="attention-item" onClick={()=>goto('Confirmación de pagos')}><span className="attention-icon pink"><CreditCard size={20}/></span><div><strong>{pending.length} pagos por confirmar</strong><small>Confirma antes de contar con ellos</small></div><ArrowUpRight size={17}/></button><div className="editorial-note"><span>Un par más,<br/><em>una venta más.</em></span><p>El siguiente paso lo das tú.</p></div></section></div>
    <section className="panel suite-section"><div className="panel-heading"><div><span className="eyebrow">PEDIDOS Y ENTREGAS</span><h2>Cada pedido tiene su próximo paso.</h2></div><button className="text-button" onClick={()=>goto('Pedidos')}>Gestionar pedidos <ArrowRight size={15}/></button></div><div className="mini-metrics"><span><strong>{data.orders.filter(o=>o.status==='new').length}</strong> nuevos</span><span><strong>{data.orders.filter(o=>['confirmed','preparing','ready'].includes(o.status)).length}</strong> en preparación o listos</span><span><strong>{data.orders.filter(o=>o.status==='sent').length}</strong> enviados</span><span><strong>{data.products.reduce((n,p)=>n+p.reserved,0)}</strong> pares reservados</span><span><strong>{data.lines.filter(l=>data.documents.some(d=>d.id===l.document_id&&d.kind==='sale'&&d.status==='active')).reduce((n,l)=>n+l.quantity,0)}</strong> pares vendidos netos</span></div><div className="upcoming-orders">{data.orders.filter(o=>!['delivered','cancelled','returned'].includes(o.status)).sort((a,b)=>a.delivery_date.localeCompare(b.delivery_date)).slice(0,5).map(o=><button key={o.id} onClick={()=>goto('Entregas pendientes')}><strong>#{o.number} · {data.clients.find(c=>c.id===o.client_id)?.name}</strong><small>{o.delivery_date}</small><span>{currency(o.total)}</span></button>)}</div>{!data.orders.length&&<p className="muted">Crea tu primer pedido desde el módulo Pedidos; sus reservas y cobros se conectarán aquí.</p>}</section>
    <div className="dashboard-bottom"><section className="panel"><div className="panel-heading"><div><span className="eyebrow">LOS FAVORITOS</span><h2>Diseños que van contigo</h2></div><button className="text-button" onClick={()=>goto('Inventario')}>Ver colección <ArrowRight size={15}/></button></div>{bestsellers.length?bestsellers.map((p,i)=><div className="bestseller" key={p.id}><span className="rank">0{i+1}</span><div className="product-swatch"><Package size={21}/></div><div><strong>{p.name}</strong><small>{p.sku}</small></div><span>{p.sold} pares</span></div>):<Empty text="Tus diseños más vendidos aparecerán después de registrar ventas."/>}</section><section className="panel quick-panel"><span className="eyebrow">UN BUEN SIGUIENTE PASO</span><h2>Haz espacio para crecer.</h2><p className="muted">Los movimientos de hoy construyen el negocio de mañana.</p><button onClick={()=>setForm('product')}><Plus size={18}/>Agregar un diseño<ArrowUpRight size={17}/></button><button onClick={()=>setForm('purchase')}><ArrowDownLeft size={18}/>Registrar una compra<ArrowUpRight size={17}/></button><button onClick={()=>setForm('expense')}><Wallet size={18}/>Registrar un gasto<ArrowUpRight size={17}/></button></section></div>
   </>}
   {page==='Inventario'&&<><div className="action-grid"><button className="secondary" onClick={()=>setImporting(true)}>Importar CSV / Excel</button></div><div className="mini-metrics"><span><strong>{data.products.length}</strong> diseños</span><span><strong>{metrics.pairs}</strong> pares físicos</span><span><strong>{currency(metrics.inventory_value)}</strong> valor a costo</span><span><strong>{low.length}</strong> por reponer</span></div><div className="toolbar"><label className="search"><Search size={17}/><input aria-label="Buscar productos" placeholder="Busca nombre, SKU o color…" value={search} onChange={e=>setSearch(e.target.value)}/></label><select aria-label="Categoría" value={category} onChange={e=>setCategory(e.target.value)}><option value="">Todas las categorías</option>{Array.from(new Set(data.products.map(p=>p.category).filter(Boolean))).map(c=><option key={c}>{c}</option>)}</select><select aria-label="Ordenar" value={sort} onChange={e=>setSort(e.target.value)}><option value="name">Nombre</option><option value="stock">Menor inventario</option><option value="price">Menor precio</option><option value="sales">Más vendidos</option></select><div className="segmented"><button className={!gallery?'active':''} aria-label="Vista tabla" onClick={()=>setGallery(false)}><List size={17}/></button><button className={gallery?'active':''} aria-label="Vista galería" onClick={()=>setGallery(true)}><Grid2X2 size={17}/></button></div><button className="secondary" onClick={()=>exportCsv('inventario-sockit.csv',[['SKU','Nombre','Categoría','Color','Talla','Existencias','Costo promedio','Precio'],...filteredProducts.map(p=>[p.sku,p.name,p.category,p.color,p.size,p.stock,p.average_cost,p.price])])}><Download size={16}/>CSV</button></div>{!filteredProducts.length?<div className="panel"><Empty text={data.products.length?'No hay diseños que coincidan con tu búsqueda.':'Tu primera colección empieza aquí. Agrega un diseño y registra su compra para incorporar existencias.'} action={!data.products.length&&<button className="primary" onClick={()=>setForm('product')}>Agregar mi primer diseño</button>}/></div>:gallery?<div className="product-grid">{filteredProducts.map(p=><article className="product-card" key={p.id}><div className="product-art">{p.photo_id?<button className="product-photo-trigger" onClick={()=>setPhotoGallery(p)} aria-label={`Ver fotografías de ${p.name}`}><img src={`/api/files/${p.photo_id}`} alt={p.name}/></button>:<Package size={56} strokeWidth={1}/>}<span>{p.category||'Sin categoría'}</span></div><div><span className="eyebrow">{p.sku}</span><h3>{p.name}</h3><p>{[p.color,p.size].filter(Boolean).join(' · ')||'Sin variante indicada'}</p><div className="product-card-bottom"><strong>{currency(p.price)}</strong><span className={`badge ${p.stock<=p.minimum?'warning':''}`}>{p.stock} pares</span></div><small>Costo promedio {currency(p.average_cost)}</small><button className="text-button" onClick={()=>{setEditing(p);setForm('edit_product');}}>Editar diseño</button></div></article>)}</div>:<div className="panel table-wrap"><table><thead><tr><th>Diseño / SKU</th><th>Categoría</th><th>Variante</th><th>Físicos</th><th>Reservados</th><th>Disponibles</th><th>Costo promedio</th><th>Precio</th><th>Margen estimado</th><th>Acción</th></tr></thead><tbody>{filteredProducts.map(p=><tr key={p.id}><td><strong>{p.name}</strong><small>{p.sku}</small></td><td>{p.category||'—'}</td><td>{[p.color,p.size].filter(Boolean).join(' / ')||'—'}</td><td><span className={`badge ${p.stock<=p.minimum?'warning':''}`}>{p.stock} pares</span></td><td>{p.reserved}</td><td>{p.available}</td><td>{currency(p.average_cost)}</td><td>{currency(p.price)}</td><td>{Number(p.price)>0?`${((Number(p.price)-Number(p.average_cost))/Number(p.price)*100).toFixed(1)} %`:'—'}</td><td><button className="text-button" onClick={()=>{setEditing(p);setForm('edit_product');}}>Editar {p.active?'':'(inactivo)'}</button></td></tr>)}</tbody></table></div>}<p className="footnote">La unidad base es el par. Las existencias se incorporan mediante compras; los costos se calculan con promedio ponderado móvil.</p></>}
   {(page==='Compras'||page==='Ventas')&&<><div className="toolbar"><label className="search"><Search size={17}/><input aria-label="Buscar registros" placeholder="Busca contacto o referencia…" value={search} onChange={e=>setSearch(e.target.value)}/></label><label className="date-filter">Desde<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label className="date-filter">Hasta<input type="date" value={to} min={from} onChange={e=>setTo(e.target.value)}/></label><button className="secondary" onClick={()=>exportCsv(`${page.toLowerCase()}-sockit.csv`,[['ID','Fecha','Contacto','Referencia','Total','Costo de venta'],...filteredDocs.map(d=>[d.id,dateLabel(d.created_at),d.contact,d.reference,d.total,d.cogs])])}><Download size={16}/>Exportar CSV</button></div><div className="mini-metrics"><span><strong>{filteredDocs.length}</strong> registros en el filtro</span><span><strong>{currency(filteredDocs.filter(d=>d.status==='active').reduce((a,d)=>a+Math.round(Number(d.total)*100),0)/100)}</strong> total filtrado</span></div><div className="panel table-wrap">{filteredDocs.length?<table><thead><tr><th>Fecha / registro</th><th>{page==='Compras'?'Proveedor':'Cliente'}</th><th>Referencia</th><th>Total</th><th>{page==='Compras'?'Por pagar':'Por cobrar'}</th><th>Detalle</th></tr></thead><tbody>{filteredDocs.map(d=>{const paid=d.kind==='sale'?paidFor(d.id):-data.movements.filter(m=>m.document_id===d.id&&m.kind==='purchase').reduce((a,m)=>a+Number(m.amount),0);return <tr key={d.id}><td>{dateLabel(d.created_at)}<small>{d.id.slice(0,8).toUpperCase()}</small></td><td><strong>{d.contact}</strong>{d.status==='reversed'&&<small>Anulada / devuelta</small>}</td><td>{d.reference||'—'}</td><td>{currency(d.total)}</td><td><span className={`badge ${Number(d.total)>paid?'warning':''}`}>{d.status==='reversed'?'Anulada':currency(Number(d.total)-paid)}</span></td><td><button className="text-button" onClick={()=>setDetail(d)}>Abrir <ArrowUpRight size={16}/></button></td></tr>;})}</tbody></table>:<Empty text="Todavía no hay registros para este filtro. Registra una operación y quedará guardada con su historial."/>}</div><p className="footnote">Horarios de República Dominicana. Los registros financieros no se eliminan. {page==='Ventas'?'Los cobros bancarios requieren confirmación manual.':'Los costos de adquisición se distribuyen por cantidad de pares.'}</p></>}
   {page==='Confirmación de pagos'&&<><div className="metric-grid three"><Metric label="Por cobrar" value={currency(metrics.receivables)} detail="Facturado menos cobros confirmados" onClick={()=>goto('Ventas')}/><Metric label="Por confirmar" value={currency(pending.reduce((n,p)=>n+Number(p.amount),0))} detail={`${pending.length} pagos reportados`} accent onClick={()=>document.getElementById('payment-table')?.scrollIntoView({behavior:reduced?'instant':'smooth'})}/><Metric label="Cobros netos" value={currency(metrics.collections)} detail="Confirmados menos reversos" onClick={()=>goto('Movimientos')}/></div><div className="section-heading"><h2>Confirmación de pagos</h2><button className="secondary" onClick={()=>setForm('payment')}><Plus size={16}/>Reportar abono</button></div><p className="notice">Un comprobante o un reporte no confirma un pago. Verifica el ingreso en tu cuenta antes de confirmar. Cada movimiento registra fecha y responsable.</p><div className="panel table-wrap" id="payment-table">{data.payments.length?<table><thead><tr><th>Cliente / referencia</th><th>Cuenta</th><th>Monto</th><th>Estado</th><th>Verificación</th><th>Acciones</th></tr></thead><tbody>{data.payments.map(p=><tr key={p.id}><td><strong>{data.documents.find(d=>d.id===p.document_id)?.contact??data.clients.find(c=>c.id===data.orders.find(o=>o.id===p.order_id)?.client_id)?.name}</strong><small>{p.reference||p.id.slice(0,8)}</small></td><td>{p.account==='cash'?'Efectivo':data.accounts.find(a=>a.id===p.account_id)?.name??'Banco histórico'}<small>{p.method}</small></td><td>{currency(p.amount)}<small>Comisión {currency(p.fee??0)} · Neto {currency(Number(p.amount)-Number(p.fee??0))}</small>{p.receipt_id&&<a href={`/api/files/${p.receipt_id}`} target="_blank" rel="noreferrer">Ver comprobante</a>}</td><td><span className={`badge ${p.status==='pending'?'warning':''}`}>{paymentLabel[p.status]}</span></td><td>{p.confirmed_at?<><small>{dateLabel(p.confirmed_at)}</small><small>Usuario {p.confirmed_by?.slice(0,8)}</small></>:'Sin confirmar'}</td><td><div className="row-actions">{p.status==='pending'&&<><button className="secondary" disabled={busy} onClick={()=>{if(window.confirm(`¿Verificaste el ingreso de ${currency(p.amount)}?`))void run('confirm_payment',{payment_id:p.id});}}><Check size={14}/>Confirmar</button><button className="text-button danger" disabled={busy} onClick={()=>{if(window.confirm('¿Rechazar este pago reportado?'))void run('reject_payment',{payment_id:p.id});}}>Rechazar</button></>}{p.status==='confirmed'&&<button className="text-button danger" disabled={busy} onClick={()=>{if(window.confirm('¿Reversar este cobro? Se registrará una salida correctiva y volverá a quedar pendiente por cobrar.'))void run('reverse_payment',{payment_id:p.id});}}>Reversar cobro</button>}</div></td></tr>)}</tbody></table>:<Empty text="No tienes pagos reportados. Los abonos de ventas aparecerán aquí."/>}</div></>}
   {page==='Finanzas'&&<><div className="metric-grid"><Metric label="Patrimonio" value={currency(metrics.equity)} detail="Activos menos pasivos" accent onClick={()=>document.getElementById('financial-summary')?.scrollIntoView()}/><Metric label="Capital aportado" value={currency(metrics.capital)} detail="Aportaciones, no ventas" onClick={()=>setForm('capital')}/><Metric label="Ganancia bruta" value={currency(metrics.gross_profit)} detail="Ventas netas menos costo vendido" onClick={()=>goto('Ventas')}/><Metric label="Ganancia neta" value={currency(metrics.net_profit)} detail="Ganancia bruta menos gastos" onClick={()=>goto('Movimientos')}/></div><div className="finance-grid"><section className="panel" id="financial-summary"><div className="panel-heading"><h2>Tu balance, en claro.</h2><span className="badge">Acumulado</span></div><dl className="financial-list">{[['Efectivo',metrics.cash],['Bancos',metrics.bank],['Inventario a costo',metrics.inventory_value],['Cuentas por cobrar',metrics.receivables],['Cuentas por pagar',-metrics.payables],['Anticipos de clientes',-metrics.customer_deposits],['Patrimonio',metrics.equity]].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{currency(value)}</dd></div>)}</dl></section><section className="panel"><h2>Cada peso tiene su lugar.</h2><dl className="financial-list">{[['Ventas facturadas',metrics.revenue],['Costo de mercancía vendida',-metrics.cogs],['Gastos operativos',-metrics.expenses],['Ganancia neta',metrics.net_profit],['Cobros confirmados netos',metrics.collections],['Retiros personales',metrics.withdrawals]].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{currency(value)}</dd></div>)}</dl><p className="footnote">Margen neto: {metrics.revenue>0?`${(metrics.net_profit/metrics.revenue*100).toFixed(1)} %`:'Sin ventas'}. Comprar inventario no duplica gastos.</p></section></div><div className="action-grid">{(['capital','expense','withdrawal','transfer'] as FormKind[]).map(kind=><button key={kind} className="secondary" onClick={()=>kind==='transfer'?setSuiteTransfer(true):setForm(kind)}><Plus size={17}/>{titles[kind]}</button>)}</div><p className="footnote">El efectivo y los bancos se consolidan aquí. Consulta Bancos y cuentas para ver saldos individuales y conciliaciones. Los anticipos sin facturar se presentan como obligaciones con clientes.</p></>}
   {page==='Movimientos'&&<><section className="panel"><div className="panel-heading"><h2>Historial financiero</h2><button className="secondary" onClick={()=>exportCsv('movimientos-sockit.csv',[['Fecha','Concepto','Tipo','Cuenta','Monto'],...data.movements.map(m=>[dateLabel(m.created_at),m.description,kindLabel[m.kind],m.account,m.amount])])}><Download size={16}/>CSV</button></div><div className="table-wrap">{data.movements.length?<table><thead><tr><th>Fecha</th><th>Concepto</th><th>Tipo</th><th>Cuenta</th><th>Monto</th></tr></thead><tbody>{data.movements.map(m=><tr key={m.id}><td>{dateLabel(m.created_at)}<small>{m.id.slice(0,8)}</small></td><td>{m.description}</td><td>{kindLabel[m.kind]}</td><td>{m.account==='cash'?'Efectivo':'Banco'}</td><td className={Number(m.amount)<0?'negative':'positive'}>{currency(m.amount)}</td></tr>)}</tbody></table>:<Empty text="Tu historial financiero aparecerá con la primera aportación, compra o venta cobrada."/>}</div></section><section className="panel inventory-ledger"><h2>Historial de inventario</h2><div className="table-wrap">{data.inventory_movements.length?<table><thead><tr><th>Fecha</th><th>Diseño</th><th>Movimiento</th><th>Costo histórico por par</th></tr></thead><tbody>{data.inventory_movements.map(m=><tr key={m.id}><td>{dateLabel(m.created_at)}</td><td>{data.products.find(p=>p.id===m.product_id)?.name}</td><td>{m.quantity>0?'+':''}{m.quantity} pares</td><td>{currency(m.unit_cost)}</td></tr>)}</tbody></table>:<Empty text="Las entradas y salidas conservarán su documento de origen y costo histórico."/>}</div></section></>}
   </motion.div><footer className="footer"><span>SOCKIT <i>Business Manager</i></span><small>Hecho para cuidar lo que estás creando.</small></footer>
  </main></div>
  {toast&&<div className="toast" role="status"><AlertCircle size={18}/><span>{toast}</span><button className="icon-button" aria-label="Cerrar notificación" onClick={()=>setToast('')}><X size={16}/></button></div>}
  {photoGallery&&<Dialog title={`Fotografías · ${photoGallery.name}`} onClose={()=>setPhotoGallery(null)}><div className="photo-gallery">{(photoGallery.photo_ids?.length?photoGallery.photo_ids:photoGallery.photo_id?[photoGallery.photo_id]:[]).map(id=><img key={id} src={`/api/files/${id}`} alt={photoGallery.name}/>)}</div></Dialog>}
  {suiteTransfer&&<SuiteForm kind="bank_transfer" data={data} onClose={()=>setSuiteTransfer(false)}/>}
  {suiteReturn!==null&&<SuiteForm kind="sale_return" data={data} initial={{document_id:suiteReturn}} onClose={()=>setSuiteReturn(null)}/>}
  {importing&&<ImportInventory onClose={()=>setImporting(false)}/>}
  {form&&<OperationForm kind={form} data={data} selectedProduct={editing} initialDocument={initialDocument} onClose={()=>{setForm(null);setEditing(null);setInitialDocument('');}} onSaved={()=>{setForm(null);setEditing(null);setInitialDocument('');setToast('Guardado. Tu negocio ya está al día.');router.refresh();}}/>}
  {detail&&<Dialog title={detail.kind==='sale'?'Detalle de venta':'Detalle de compra'} onClose={()=>setDetail(null)}><p><strong>{detail.contact}</strong> · {dateLabel(detail.created_at)}</p><p className="muted">Referencia: {detail.reference||'Sin referencia'} · {detail.id}</p><div className="table-wrap"><table><thead><tr><th>Diseño</th><th>Pares</th><th>Precio</th><th>Costo histórico</th></tr></thead><tbody>{data.original_lines.filter(l=>l.document_id===detail.id).map(l=><tr key={l.product_id}><td>{data.products.find(p=>p.id===l.product_id)?.name}</td><td>{l.quantity}</td><td>{currency(l.unit_price)}</td><td>{currency(l.unit_cost)}</td></tr>)}</tbody></table></div>{detail.kind==='purchase'&&<p>Costos de adquisición incluidos: {currency(detail.acquisition)}</p>}<div className="detail-total">Total <strong>{currency(detail.total)}</strong></div>{detail.kind==='sale'&&<><p>Ganancia bruta neta actual: {currency(detail.status==='active'?Number(detail.total)-Number(detail.cogs):0)}</p><p>Pendiente de cobro: {currency(detail.status==='active'?Number(detail.total)-paidFor(detail.id):0)}</p><button className="secondary" onClick={()=>{setDetail(null);goto('Confirmación de pagos');}}>Ir a cobros <ArrowRight size={16}/></button></>}{detail.status==='active'&&<div className="action-grid">{detail.kind==='purchase'?<button className="secondary" onClick={()=>{setInitialDocument(detail.id);setDetail(null);setForm('purchase_payment');}}>Pagar a proveedor</button>:<button className="secondary" onClick={()=>{setInitialDocument(detail.id);setDetail(null);setForm('reverse_sale');}}>Devolver o anular venta</button>}</div>}{detail.kind==='sale'&&detail.status==='active'&&<button className="secondary" onClick={()=>{setDetail(null);setSuiteReturn(detail.id);}}>Devolución parcial</button>}<p className="footnote">Original facturado: {currency(detail.original_total??detail.total)}. El historial de devoluciones conserva cantidades, costo y motivo.</p>{data.returns.filter(r=>r.document_id===detail.id).map(r=><p key={r.id}>{dateLabel(r.created_at)} · {r.reason} · {currency(r.amount)}</p>)}</Dialog>}
 </div>;
}

function Dialog({title,onClose,children,locked=false}:{title:string;onClose:()=>void;children:React.ReactNode;locked?:boolean}) {
 const ref=useRef<HTMLDialogElement>(null);
 useEffect(()=>{const el=ref.current;el?.showModal();return()=>{el?.close();};},[]);
 return <dialog ref={ref} className="dialog" onCancel={e=>{e.preventDefault();if(!locked)onClose();}} aria-label={title}><div className="dialog-header"><h2>{title}</h2><button type="button" className="icon-button" aria-label="Cerrar formulario" disabled={locked} onClick={onClose}><X/></button></div>{children}</dialog>;
}
function OperationForm({kind,data,onClose,onSaved,selectedProduct,initialDocument}:{kind:FormKind;data:Snapshot;onClose:()=>void;onSaved:()=>void;selectedProduct:Product|null;initialDocument:string}) {
 const [busy,setBusy]=useState(false);const [error,setError]=useState('');
 const [lines,setLines]=useState([{product_id:'',quantity:1,unit_price:0}]);
 const [acquisition,setAcquisition]=useState(0);
 const [discount,setDiscount]=useState(0);
 const [deliveryCharge,setDeliveryCharge]=useState(0);
 const [photoId,setPhotoId]=useState(selectedProduct?.photo_id??'');
 const [photoIds,setPhotoIds]=useState<string[]>(selectedProduct?.photo_ids?.length?selectedProduct.photo_ids:selectedProduct?.photo_id?[selectedProduct.photo_id]:[]);
 const [receiptId,setReceiptId]=useState('');
 const [uploading,setUploading]=useState(false);
 const key=useRef<string>('');
 const isDocument=kind==='purchase'||kind==='sale';
 const total=lines.reduce((n,l)=>n+Math.round(l.quantity*l.unit_price*100),0)/100+(kind==='purchase'?acquisition:deliveryCharge)-discount;
 const outstanding=data.documents.filter(d=>d.kind==='sale'&&d.status==='active'&&Number(d.total)>data.payments.filter(p=>p.document_id===d.id&&['pending','confirmed'].includes(p.status)).reduce((n,p)=>n+Number(p.amount),0));
 async function submit(event:React.FormEvent<HTMLFormElement>){
  event.preventDefault();if(busy)return;setBusy(true);setError('');
  if(!key.current)key.current=crypto.randomUUID();
  const f=new FormData(event.currentTarget);const string=(name:string)=>String(f.get(name)??'');const num=(name:string)=>Number(f.get(name)||0);
  let payload:unknown;
  if(kind==='edit_product')payload={product_id:selectedProduct?.id,sku:string('sku'),name:string('name'),category:string('category'),color:string('color'),size:string('size'),price:num('price'),minimum:num('minimum'),active:f.get('active')==='on'};
  else if(kind==='reverse_sale')payload={document_id:string('document_id'),description:string('description')};
  else if(kind==='product')payload={sku:string('sku'),name:string('name'),category:string('category'),color:string('color'),size:string('size'),price:num('price'),minimum:num('minimum')};
  else if(isDocument)payload={contact:string('contact'),reference:string('reference'),account:string('account'),paid:num('paid'),acquisition:kind==='purchase'?acquisition:0,lines};
  else if(kind==='payment'||kind==='purchase_payment')payload={document_id:string('document_id'),account:string('account'),amount:num('amount'),reference:string('reference')};
  else payload={account:string('account'),amount:num('amount'),description:string('description')};
  const selector=string('account_selector');
  const extras:Record<string,unknown>={account:selector==='cash'?'cash':'bank',account_id:['cash','bank',''].includes(selector)?'':selector};
  if(kind==='product'||kind==='edit_product')Object.assign(extras,{photo_id:photoId,photo_ids:photoIds,collection:string('collection'),sock_type:string('sock_type'),brand:string('brand')||'SOCKIT',supplier_id:string('supplier_id')});
  if(isDocument)Object.assign(extras,{discount,delivery_charge:kind==='sale'?deliveryCharge:0,client_id:string('client_id'),supplier_id:string('supplier_id'),due_date:string('due_date')});
  if(kind==='sale'||kind==='payment')Object.assign(extras,{method:string('method')||'cash',fee:num('fee'),origin_bank:string('origin_bank'),receipt_id:receiptId});
  if(kind==='expense')extras.expense_category=string('expense_category');
  if(['capital','expense','withdrawal','transfer','purchase_payment','sale','purchase','payment','product','edit_product'].includes(kind))payload={...(payload as object),...extras};
  try{const r=await saveOperation(kind,payload,key.current);if(r.ok)onSaved();else setError(r.error??'No se pudo guardar');}catch{setError('No se recibió confirmación. Mantén este formulario y vuelve a intentar para evitar duplicados.');}finally{setBusy(false);}
 }
 return <Dialog title={titles[kind]} onClose={onClose} locked={busy||uploading}><form onSubmit={submit} className="operation-form"><fieldset disabled={busy}>
 {(kind==='product'||kind==='edit_product')&&<><p className="muted">Agrega el diseño. Para incorporar existencias y su costo, registra una compra después.</p><div className="form-grid"><label>SKU único<input name="sku" defaultValue={selectedProduct?.sku} required maxLength={60} placeholder="SK-COSTILLA-01"/></label><label>Nombre del diseño<input name="name" defaultValue={selectedProduct?.name} required maxLength={160} placeholder="Costilla borgoña"/></label><label>Categoría<input name="category" defaultValue={selectedProduct?.category} maxLength={100} placeholder="Clásicas"/></label><label>Color<input name="color" defaultValue={selectedProduct?.color} maxLength={80} placeholder="Borgoña"/></label><label>Talla<input name="size" defaultValue={selectedProduct?.size} maxLength={40} placeholder="35–40"/></label><label>Precio de venta por par (RD$)<input name="price" defaultValue={selectedProduct?.price} required type="number" step="0.01" min="0" max="999999999"/></label><label>Alerta de inventario mínimo<input name="minimum" required type="number" min="0" step="1" defaultValue={selectedProduct?.minimum??5}/></label></div><div className="form-grid"><label>Colección<input name="collection" defaultValue={selectedProduct?.collection}/></label><label>Tipo de media<input name="sock_type" defaultValue={selectedProduct?.sock_type}/></label><label>Marca<input name="brand" defaultValue={selectedProduct?.brand??'SOCKIT'}/></label><SupplierSelect data={data} initial={selectedProduct?.supplier_id}/></div><FileUpload purpose="product" onBusy={setUploading} initial={selectedProduct?.photo_id} onChange={id=>{setPhotoId(id);setPhotoIds(ids=>Array.from(new Set([...ids,id])));}}/><div className="photo-thumbnails">{photoIds.map(id=><div key={id}><img src={`/api/files/${id}`} alt="Fotografía del diseño"/><button type="button" className="text-button" onClick={()=>{const next=photoIds.filter(p=>p!==id);setPhotoIds(next);setPhotoId(next[0]??'');}}>Desvincular</button></div>)}</div>{kind==='edit_product'&&<label className="checkbox-label"><input name="active" type="checkbox" defaultChecked={selectedProduct?.active}/>Diseño activo para compras y ventas nuevas</label>}</>}
 {isDocument&&<><div className="form-grid">{kind==='sale'?<label>Cliente registrado (opcional)<select aria-label="Cliente registrado" name="client_id" onChange={e=>{const c=data.clients.find(c=>c.id===e.target.value);const input=e.target.form?.elements.namedItem('contact') as HTMLInputElement|null;if(c&&input)input.value=c.name;}}><option value="">Sin asociar cliente</option>{data.clients.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>:<SupplierSelect data={data}/>}<label>Fecha límite de pago (opcional)<input name="due_date" type="date"/></label></div><div className="form-grid"><label>{kind==='purchase'?'Proveedor':'Cliente'}<input name="contact" required maxLength={160}/></label><label>Referencia / factura<input name="reference" maxLength={160}/></label></div>{kind==='sale'&&data.presentations.some(p=>p.active)&&<label>Usar presentación o combo<select aria-label="Usar presentación o combo" onChange={e=>{const p=data.presentations.find(p=>p.id===e.target.value);if(p)setLines(p.lines.map(l=>({...l})));}}><option value="">Selecciona una presentación…</option>{data.presentations.filter(p=>p.active).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>}<div className="line-heading"><strong>Diseños · cantidades en pares</strong><button type="button" className="text-button" onClick={()=>setLines([...lines,{product_id:'',quantity:1,unit_price:0}])}><Plus size={15}/>Agregar línea</button></div>{lines.map((line,index)=><div className="order-line" key={index}><label>Diseño<select aria-label="Diseño" required value={line.product_id} onChange={e=>{const p=data.products.find(p=>p.id===e.target.value);setLines(lines.map((l,i)=>i===index?{...l,product_id:e.target.value,unit_price:Number(kind==='sale'?p?.price??0:p?.average_cost??0)}:l));}}><option value="">Selecciona…</option>{data.products.filter(p=>p.active).map(p=><option key={p.id} value={p.id}>{p.name} · {p.sku} ({p.stock} pares)</option>)}</select></label><label>Pares<input required type="number" min="1" max="1000000" step="1" value={line.quantity} onChange={e=>setLines(lines.map((l,i)=>i===index?{...l,quantity:Number(e.target.value)}:l))}/></label><label>{kind==='purchase'?'Costo / par':'Precio / par'}<input required type="number" min="0" max="999999999" step="0.01" value={line.unit_price} onChange={e=>setLines(lines.map((l,i)=>i===index?{...l,unit_price:Number(e.target.value)}:l))}/></label><button type="button" className="icon-button" disabled={lines.length===1} aria-label={`Quitar línea ${index+1}`} onClick={()=>setLines(lines.filter((_,i)=>i!==index))}><X size={16}/></button></div>)}{!data.products.length&&<p className="notice">Primero agrega un diseño en Inventario.</p>}{kind==='purchase'&&<label>Transporte, flete y adquisición (RD$)<input type="number" min="0" step="0.01" value={acquisition} onChange={e=>setAcquisition(Number(e.target.value))}/><small>Se capitaliza y distribuye por cantidad de pares.</small></label>}<div className="form-grid"><label>Descuento general (RD$)<input type="number" min="0" step="0.01" value={discount} onChange={e=>setDiscount(Number(e.target.value))}/></label>{kind==='sale'&&<label>Entrega cobrada al cliente (RD$)<input type="number" min="0" step="0.01" value={deliveryCharge} onChange={e=>setDeliveryCharge(Number(e.target.value))}/></label>}</div><div className="detail-total">Total de la operación<strong>{currency(total)}</strong></div><div className="form-grid"><label>{kind==='purchase'?'Monto pagado':'Abono recibido'} (RD$)<input name="paid" type="number" min="0" max={total} step="0.01" defaultValue="0"/></label><AccountSelect data={data}/></div><p className="notice">{kind==='sale'?'El efectivo se registra como recibido al guardar. El banco queda pendiente de confirmación manual.':'El monto pagado sale de la cuenta seleccionada. El resto queda como deuda con el proveedor.'}</p>{kind==='sale'&&<p className="footnote">Paquetes y combos: indica los pares de cada SKU (3, 6 o 12). El precio es por par; registra el precio neto acordado.</p>}</>}
 {(kind==='payment'||kind==='purchase_payment')&&<><label>{kind==='payment'?'Venta con saldo disponible para reportar':'Compra con deuda pendiente'}<select name="document_id" defaultValue={initialDocument} required><option value="">Selecciona una venta…</option>{(kind==='payment'?outstanding:data.documents.filter(d=>d.kind==='purchase'&&Number(d.total)>-data.movements.filter(m=>m.document_id===d.id&&m.kind==='purchase').reduce((n,m)=>n+Number(m.amount),0))).map(d=><option key={d.id} value={d.id}>{d.contact} · {d.id.slice(0,8)} · {currency(d.total)}</option>)}</select></label><div className="form-grid"><label>Monto del abono (RD$)<input name="amount" required type="number" min="0.01" max="999999999" step="0.01"/></label><AccountSelect data={data}/></div><label>Referencia<input name="reference" maxLength={160}/></label><p className="notice">{kind==='payment'?'El abono se reportará como pendiente. Debes verificarlo y confirmarlo para aumentar el saldo disponible.':'El pago disminuirá la cuenta seleccionada y la deuda con el proveedor. No genera un gasto operativo adicional.'}</p></>}
 {kind==='reverse_sale'&&<><label>Venta<select name="document_id" defaultValue={initialDocument} required><option value="">Selecciona…</option>{data.documents.filter(d=>d.kind==='sale'&&d.status==='active').map(d=><option key={d.id} value={d.id}>{d.contact} · {d.id.slice(0,8)} · {currency(d.total)}</option>)}</select></label><label>Motivo documentado<input name="description" required maxLength={250}/></label><p className="notice">Devuelve todos los pares al inventario a su costo histórico, reembolsa los cobros confirmados y revierte los pagos pendientes. Verifica que recibiste la mercancía. No se borra el historial.</p></>}
 {kind==='expense'&&<label>Categoría de gasto<select name="expense_category" aria-label="Categoría de gasto">{['Transporte','Publicidad','Empaques','Comisiones','Entregas','Alquiler','Otros',...data.catalogs.filter(c=>c.kind==='expense_category'&&c.active).map(c=>c.label)].map(c=><option key={c} value={c}>{c}</option>)}</select></label>}
 {!isDocument&&kind!=='product'&&kind!=='edit_product'&&kind!=='reverse_sale'&&kind!=='purchase_payment'&&kind!=='payment'&&<><div className="form-grid"><label>Monto (RD$)<input name="amount" required type="number" min="0.01" max="999999999" step="0.01"/></label><AccountSelect data={data} title={kind==='transfer'?'Cuenta de origen':'Cuenta'}/></div><label>Concepto<input name="description" required maxLength={250}/></label><p className="notice">{kind==='capital'?'El capital aumenta la cuenta disponible y el patrimonio. No es una venta.':kind==='transfer'?'Se registran dos movimientos: salida de la cuenta seleccionada y entrada a la otra. No genera ingresos.':kind==='withdrawal'?'El retiro disminuye tu cuenta y tu patrimonio. No es un gasto del negocio.':'El gasto reduce el saldo disponible y la ganancia neta. No uses este formulario para compras de inventario.'}</p></>}
 {(kind==='sale'||kind==='payment')&&<><PaymentFields data={data}/><FileUpload purpose="receipt" onBusy={setUploading} onChange={setReceiptId}/></>}
 </fieldset>{error&&<p className="error" role="alert">{error}</p>}<div className="dialog-footer"><button type="button" className="secondary" disabled={busy||uploading} onClick={onClose}>Cancelar</button><button className="primary" disabled={busy||uploading||(isDocument&&!data.products.length)}>{busy?'Guardando y verificando…':'Guardar movimiento'}{!busy&&<Check size={17}/>}</button></div></form></Dialog>;
}
function AccountSelect({title='Cuenta',data}:{title?:string;data:Snapshot}){return <label>{title}<select name="account_selector" aria-label={title} defaultValue="cash"><option value="cash">Efectivo</option><option value="bank">Banco histórico agregado</option>{data.accounts.filter(a=>a.active).map(a=><option key={a.id} value={a.id}>{a.name} · {a.masked_number}</option>)}</select></label>;}
function SupplierSelect({data,initial}:{data:Snapshot;initial?:string|null}){return <label>Proveedor registrado<select aria-label="Proveedor registrado" name="supplier_id" defaultValue={initial??''} onChange={e=>{const supplier=data.suppliers.find(s=>s.id===e.target.value);const input=e.target.form?.elements.namedItem('contact') as HTMLInputElement|null;if(supplier&&input)input.value=supplier.name;}}><option value="">Sin asociar proveedor</option>{data.suppliers.filter(s=>s.active).map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label>;}
function PaymentFields({data}:{data:Snapshot}){return <div className="form-grid"><label>Método de pago<select aria-label="Método de pago" name="method"><option value="cash">Efectivo</option><option value="transfer">Transferencia</option><option value="deposit">Depósito</option><option value="debit_card">Tarjeta de débito</option><option value="credit_card">Tarjeta de crédito</option>{data.catalogs.filter(c=>c.kind==='payment_method'&&c.active).map(c=><option key={c.id} value={c.label}>{c.label}</option>)}</select></label><label>Comisión de tarjeta (RD$)<input name="fee" type="number" min="0" step="0.01" defaultValue="0"/></label><label>Banco de origen (opcional)<input name="origin_bank" maxLength={160}/></label></div>;}
